    $this->assertSame('laravel_php_framework', Str::snake('Laravel Php Framework'));
    $this->assertSame('laravel_php_framework', Str::snake('Laravel    Php      Framework   '));
    // ensure cache keys don't overlap
    $this->assertSame('laravel__php__framework', Str::snake('LaravelPhpFramework', '__'));
